import Fastify, { type FastifyInstance } from "fastify";
import fp from "fastify-plugin";

export const app = Fastify({ logger: false });

async function catalog(fastify: FastifyInstance) {
  fastify.decorate("catalog", {
    list: () => [{ id: "notebook", name: "Notebook", price: 4.5 }],
  });
}

export const catalogPlugin = fp(catalog);

app.register(catalogPlugin);
